/****** Object:  UserDefinedFunction bobsusedbookstore_dbo.ufncalculatecustomerlifetimevalue    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE   FUNCTION bobsusedbookstore_dbo.ufncalculatecustomerlifetimevalue
(
    @CustomerID INT
)
RETURNS DECIMAL(10, 2)
AS
BEGIN
    DECLARE @TotalSpent DECIMAL(10, 2);
    DECLARE @FirstOrderDate DATE;
    DECLARE @DaysSinceFirstOrder INT;
    DECLARE @LifetimeValue DECIMAL(10, 2);
    
    SELECT 
        @TotalSpent = SUM(TotalAmount),
        @FirstOrderDate = MIN(OrderDate)
    FROM bobsusedbookstore_dbo.shopping
    WHERE CustomerID = @CustomerID AND TRIM(Status) != 'Refund Requested';
    
    SET @DaysSinceFirstOrder = DATE_PART('day', @FirstOrderDate, clock_timestamp());
    
    IF @DaysSinceFirstOrder = 0
        SET @LifetimeValue = @TotalSpent;
    ELSE
        SET @LifetimeValue = (@TotalSpent / @DaysSinceFirstOrder) * 365.25;
    
    RETURN @LifetimeValue;
END;


/****** Object:  UserDefinedFunction bobsusedbookstore_dbo.ufngetaccountingenddate    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE OR REPLACE FUNCTION bobsusedbookstore_dbo.ufngetaccountingenddate()
RETURNS TIMESTAMP WITHOUT TIME ZONE 
AS 
BEGIN
    RETURN DATEADD(millisecond, -2, CAST(TIMESTAMP WITHOUT TIME ZONE, '20040701', 112));
END;


