/****** Object:  UserDefinedFunction bobsusedbookstore_dbo.ufngetdocumentstatustext    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON

            
CREATE OR REPLACE FUNCTION bobsusedbookstore_dbo.ufngetdocumentstatustext(@Status tinyint)
RETURNS VARCHAR(16) 
AS 
BEGIN
    DECLARE @ret VARCHAR(16);

    SET @ret = 
        CASE @Status
            WHEN 1 THEN 'Pending approval'
            WHEN 2 THEN 'Approved'
            WHEN 3 THEN 'Obsolete'
            ELSE '** Invalid **'
        END;
    
    RETURN @ret
END;


/****** Object:  UserDefinedFunction bobsusedbookstore_dbo.ufngetpurchaseorderstatustext    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

