CREATE OR REPLACE FUNCTION bobsusedbookstore_dbo.ufngetpurchaseorderstatustext(@Status tinyint)
RETURNS VARCHAR(15) 
AS 
BEGIN
    DECLARE @ret VARCHAR(15);

    SET @ret = 
        CASE @Status
            WHEN 1 THEN 'Pending'
            WHEN 2 THEN 'Approved'
            WHEN 3 THEN 'Rejected'
            WHEN 4 THEN 'Complete'
            ELSE '** Invalid **'
        END;
    
    RETURN @ret
END;


/****** Object:  UserDefinedFunction bobsusedbookstore_dbo.ufngetsalesorderstatustext    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON

            
CREATE OR REPLACE FUNCTION bobsusedbookstore_dbo.ufngetsalesorderstatustext(@Status tinyint)
RETURNS VARCHAR(15) 
AS 
BEGIN
    DECLARE @ret VARCHAR(15);

    SET @ret = 
        CASE @Status
            WHEN 1 THEN 'In process'
            WHEN 2 THEN 'Approved'
            WHEN 3 THEN 'Backordered'
            WHEN 4 THEN 'Rejected'
            WHEN 5 THEN 'Shipped'
            WHEN 6 THEN 'Cancelled'
            ELSE '** Invalid **'
        END;
    
    RETURN @ret
END;


