/****** Object:  View bobsusedbookstore_dbo.vwtopmembers    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


-- Create views
CREATE VIEW bobsusedbookstore_dbo.vwtopmembers AS
SELECT * 
FROM (
    SELECT TOP 50 PERCENT 
        c.CustomerID, 
        c.FirstName, 
        c.LastName, 
        SUM(o.TotalAmount) AS TotalSpent
    FROM bobsusedbookstore_dbo.members c
    JOIN bobsusedbookstore_dbo.shopping o ON c.CustomerID = o.CustomerID
    GROUP BY c.CustomerID, c.FirstName, c.LastName
    ORDER BY TotalSpent DESC
) sub;


