/****** Object:  View bobsusedbookstore_dbo.vwregionalsales    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE VIEW bobsusedbookstore_dbo.vwregionalsales (RegionName, RegionSalesSum) AS
SELECT 
    CHOOSE(RegionID, 
           'North America', 'Europe', 'Asia', 'South America', 'Africa', 
           'Australia', 'Middle East', 'Central America', 'Eastern Europe', 
           'Western Europe') AS RegionName,
    SUM(Quantity * SalePrice) AS RegionSalesSum
FROM bobsusedbookstore_dbo.productsales
GROUP BY CHOOSE(RegionID, 
                'North America', 'Europe', 'Asia', 'South America', 'Africa', 
                'Australia', 'Middle East', 'Central America', 'Eastern Europe', 
                'Western Europe');


/****** Object:  UserDefinedFunction bobsusedbookstore_dbo.ufnleadingzeros    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON

                    
CREATE OR REPLACE FUNCTION bobsusedbookstore_dbo.ufnleadingzeros(
    @Value int
) 
RETURNS varchar(8) 
WITH SCHEMABINDING 
AS 
BEGIN
    DECLARE @ReturnValue varchar(8);

    SET @ReturnValue = CAST(varchar(8), @Value);
    SET @ReturnValue = REPEAT('0', 8 - LENGTH(@ReturnValue)) + @ReturnValue;

    RETURN (@ReturnValue);
END;


