INSERT bobsusedbookstore_dbo.databaselog (DatabaseLogID, PostTime, DatabaseUser, Event, Schema, Object, TSQL, XmlEvent) VALUES (5, CAST('2025-08-25T02:04:16.823' AS DateTime), 'sqladmin', 'CREATE_PROCEDURE', 'dbo', 'uspPrintError', '
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspprinterror 
AS
BEGIN
    

    -- Print error information. 
    RAISE NOTICE '%', ''Error '' + CAST(varchar(50), ERROR_NUMBER()) +
          '', Severity '' + CAST(varchar(5), ERROR_SEVERITY()) +
          '', State '' + CAST(varchar(5), ERROR_STATE()) + 
          '', Procedure '' + COALESCE(ERROR_PROCEDURE(), ''-'') + 
          '', Line '' + CAST(varchar(5), ERROR_LINE());
