INSERT bobsusedbookstore_dbo.databaselog (DatabaseLogID, PostTime, DatabaseUser, Event, Schema, Object, TSQL, XmlEvent) VALUES (26, CAST('2025-08-25T02:04:16.947' AS DateTime), 'sqladmin', 'CREATE_PROCEDURE', 'dbo', 'uspGetTopRegion', '
-- Create procedures
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspgettopregion
    @Percent INT
AS
BEGIN
    WITH HalfYearSales AS (
        SELECT 
            psr.RegionID,
            psr.RegionName,
            COUNT(ps.SaleID) AS NumberOfSales,
            SUM(ps.TotalAmount) AS TotalSalesAmount,
            COUNT(DISTINCT ps.CustomerID) AS NumberOfMembers
        FROM 
            bobsusedbookstore_dbo.productsaleregions psr
        LEFT JOIN 
            bobsusedbookstore_dbo.productsales ps ON psr.RegionID = ps.RegionID
        WHERE 
            ps.SaleDate >= DATEADD(MONTH, -6, clock_timestamp())
        GROUP BY 
            psr.RegionID, psr.RegionName
    )
    SELECT * FROM (
        SELECT TOP 10 PERCENT * FROM HalfYearSales WHERE @Percent = 10 ORDER BY NumberOfSales DESC
        UNION ALL 
        SELECT TOP 20 PERCENT * FROM HalfYearSales WHERE @Percent = 20 ORDER BY NumberOfSales DESC
        UNION ALL 
        SELECT TOP 30 PERCENT * FROM HalfYearSales WHERE @Percent = 30 ORDER BY NumberOfSales DESC
        UNION ALL 
        SELECT TOP 40 PERCENT * FROM HalfYearSales WHERE @Percent = 40 ORDER BY NumberOfSales DESC
        UNION ALL 
        SELECT TOP 50 PERCENT * FROM HalfYearSales WHERE @Percent = 50 ORDER BY NumberOfSales DESC
    ) q
    ORDER BY NumberOfSales DESC, TotalSalesAmount DESC;
END;
', '<EVENT_INSTANCE><EventType>CREATE_PROCEDURE</EventType><PostTime>2025-08-25T02:04:16.947</PostTime><SPID>68</SPID><ServerName>EC2AMAZ-B8QKRL0</ServerName><LoginName>sqladmin</LoginName><UserName>sqladmin</UserName><DatabaseName>BobsUsedBookStore</DatabaseName><SchemaName>dbo</SchemaName><ObjectName>uspGetTopRegion</ObjectName><ObjectType>PROCEDURE</ObjectType><TSQLCommand><SetOptions ANSI_NULLS="ON" ANSI_NULL_DEFAULT="ON" ANSI_PADDING="ON" QUOTED_IDENTIFIER="ON" ENCRYPTED="FALSE" /><CommandText>
-- Create procedures
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspgettopregion
    @Percent INT
AS
BEGIN
    WITH HalfYearSales AS (
        SELECT 
            psr.RegionID,
            psr.RegionName,
            COUNT(ps.SaleID) AS NumberOfSales,
            SUM(ps.TotalAmount) AS TotalSalesAmount,
            COUNT(DISTINCT ps.CustomerID) AS NumberOfMembers
        FROM 
            bobsusedbookstore_dbo.productsaleregions psr
        LEFT JOIN 
            bobsusedbookstore_dbo.productsales ps ON psr.RegionID = ps.RegionID
        WHERE 
            ps.SaleDate &gt;= DATEADD(MONTH, -6, clock_timestamp())
        GROUP BY 
            psr.RegionID, psr.RegionName
    )
    SELECT * FROM (
        SELECT TOP 10 PERCENT * FROM HalfYearSales WHERE @Percent = 10 ORDER BY NumberOfSales DESC
        UNION ALL 
        SELECT TOP 20 PERCENT * FROM HalfYearSales WHERE @Percent = 20 ORDER BY NumberOfSales DESC
        UNION ALL 
        SELECT TOP 30 PERCENT * FROM HalfYearSales WHERE @Percent = 30 ORDER BY NumberOfSales DESC
        UNION ALL 
        SELECT TOP 40 PERCENT * FROM HalfYearSales WHERE @Percent = 40 ORDER BY NumberOfSales DESC
        UNION ALL 
        SELECT TOP 50 PERCENT * FROM HalfYearSales WHERE @Percent = 50 ORDER BY NumberOfSales DESC
    ) q
    ORDER BY NumberOfSales DESC, TotalSalesAmount DESC;
END;
</CommandText></TSQLCommand></EVENT_INSTANCE>')
INSERT bobsusedbookstore_dbo.databaselog (DatabaseLogID, PostTime, DatabaseUser, Event, Schema, Object, TSQL, XmlEvent) VALUES (27, CAST('2025-08-25T02:04:16.953' AS DateTime), 'sqladmin', 'CREATE_PROCEDURE', 'dbo', 'uspDeleteOldCoupons', '
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspdeleteoldcoupons
    @DaysOld INT
AS
BEGIN
    DECLARE @DeletedCount INT = 0;
    
    SELECT TicketID, CreatedDate
    INTO #CouponsToDelete
    FROM bobsusedbookstore_dbo.coupons
    WHERE TRIM(Status) = ''Closed'' AND ResolvedDate <= DATEADD(DAY, -@DaysOld, clock_timestamp());

    DECLARE @CouponsCount INT;
    SELECT @CouponsCount = COUNT(*) FROM #CouponsToDelete;

    IF @CouponsCount > 0
    BEGIN
        DELETE t
        FROM bobsusedbookstore_dbo.coupons t
        INNER JOIN #CouponsToDelete d ON t.TicketID = d.TicketID;
        
        SET @DeletedCount = ROW_COUNT;
        RAISE NOTICE '%', ''Deleted '' + CAST(@DeletedCount AS VARCHAR(10)) + '' coupons.'';
    END
    ELSE
    BEGIN
        RAISE NOTICE '%', ''No coupons found matching the criteria.'';
    END
END;
', '<EVENT_INSTANCE><EventType>CREATE_PROCEDURE</EventType><PostTime>2025-08-25T02:04:16.950</PostTime><SPID>68</SPID><ServerName>EC2AMAZ-B8QKRL0</ServerName><LoginName>sqladmin</LoginName><UserName>sqladmin</UserName><DatabaseName>BobsUsedBookStore</DatabaseName><SchemaName>dbo</SchemaName><ObjectName>uspDeleteOldCoupons</ObjectName><ObjectType>PROCEDURE</ObjectType><TSQLCommand><SetOptions ANSI_NULLS="ON" ANSI_NULL_DEFAULT="ON" ANSI_PADDING="ON" QUOTED_IDENTIFIER="ON" ENCRYPTED="FALSE" /><CommandText>
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspdeleteoldcoupons
    @DaysOld INT
AS
BEGIN
    DECLARE @DeletedCount INT = 0;
    
    SELECT TicketID, CreatedDate
    INTO #CouponsToDelete
    FROM bobsusedbookstore_dbo.coupons
    WHERE TRIM(Status) = ''Closed'' AND ResolvedDate &lt;= DATEADD(DAY, -@DaysOld, clock_timestamp());

    DECLARE @CouponsCount INT;
    SELECT @CouponsCount = COUNT(*) FROM #CouponsToDelete;

    IF @CouponsCount &gt; 0
    BEGIN
        DELETE t
        FROM bobsusedbookstore_dbo.coupons t
        INNER JOIN #CouponsToDelete d ON t.TicketID = d.TicketID;
        
        SET @DeletedCount = ROW_COUNT;
        RAISE NOTICE '%', ''Deleted '' + CAST(@DeletedCount AS VARCHAR(10)) + '' coupons.'';
    END
    ELSE
    BEGIN
        RAISE NOTICE '%', ''No coupons found matching the criteria.'';
    END
END;
</CommandText></TSQLCommand></EVENT_INSTANCE>')
INSERT bobsusedbookstore_dbo.databaselog (DatabaseLogID, PostTime, DatabaseUser, Event, Schema, Object, TSQL, XmlEvent) VALUES (28, CAST('2025-08-25T02:04:16.960' AS DateTime), 'sqladmin', 'CREATE_PROCEDURE', 'dbo', 'uspProcessRefunds', '
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspprocessrefunds
AS
BEGIN
    

    DECLARE @RefundCount INT = 0;
    DECLARE @MaxID INT;

    SELECT @MaxID = MAX(TicketID) FROM bobsusedbookstore_dbo.coupons;
    
    SELECT OrderID, CustomerID, TotalAmount
    INTO #RefundRequests
    FROM bobsusedbookstore_dbo.shopping
    WHERE TRIM(Status) = ''Refund Requested'';
    
    UPDATE o
    SET Status = ''Refunded''
    FROM bobsusedbookstore_dbo.shopping o
    INNER JOIN #RefundRequests r ON o.OrderID = r.OrderID;
    
    INSERT INTO bobsusedbookstore_dbo.coupons (TicketID, CustomerID, OrderID, IssueDescription, CreatedDate, Status)
    SELECT 
        @MaxID + ROW_NUMBER() OVER (ORDER BY OrderID),
        CustomerID,
        OrderID,
        ''Refund processed for $'' + CAST(TotalAmount AS VARCHAR(20)),
        clock_timestamp(),
        ''Closed''
    FROM #RefundRequests;

    SET @RefundCount = ROW_COUNT;

    RAISE NOTICE '%', ''Processed '' + CAST(@RefundCount AS VARCHAR(10)) + '' refunds.'';

    DROP TABLE #RefundRequests;
END;
', '<EVENT_INSTANCE><EventType>CREATE_PROCEDURE</EventType><PostTime>2025-08-25T02:04:16.960</PostTime><SPID>68</SPID><ServerName>EC2AMAZ-B8QKRL0</ServerName><LoginName>sqladmin</LoginName><UserName>sqladmin</UserName><DatabaseName>BobsUsedBookStore</DatabaseName><SchemaName>dbo</SchemaName><ObjectName>uspProcessRefunds</ObjectName><ObjectType>PROCEDURE</ObjectType><TSQLCommand><SetOptions ANSI_NULLS="ON" ANSI_NULL_DEFAULT="ON" ANSI_PADDING="ON" QUOTED_IDENTIFIER="ON" ENCRYPTED="FALSE" /><CommandText>
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspprocessrefunds
AS
BEGIN
    

    DECLARE @RefundCount INT = 0;
    DECLARE @MaxID INT;

    SELECT @MaxID = MAX(TicketID) FROM bobsusedbookstore_dbo.coupons;
    
    SELECT OrderID, CustomerID, TotalAmount
    INTO #RefundRequests
    FROM bobsusedbookstore_dbo.shopping
    WHERE TRIM(Status) = ''Refund Requested'';
    
    UPDATE o
    SET Status = ''Refunded''
    FROM bobsusedbookstore_dbo.shopping o
    INNER JOIN #RefundRequests r ON o.OrderID = r.OrderID;
    
    INSERT INTO bobsusedbookstore_dbo.coupons (TicketID, CustomerID, OrderID, IssueDescription, CreatedDate, Status)
    SELECT 
        @MaxID + ROW_NUMBER() OVER (ORDER BY OrderID),
        CustomerID,
        OrderID,
        ''Refund processed for $'' + CAST(TotalAmount AS VARCHAR(20)),
        clock_timestamp(),
        ''Closed''
    FROM #RefundRequests;

    SET @RefundCount = ROW_COUNT;

    RAISE NOTICE '%', ''Processed '' + CAST(@RefundCount AS VARCHAR(10)) + '' refunds.'';

    DROP TABLE #RefundRequests;
END;
</CommandText></TSQLCommand></EVENT_INSTANCE>')
INSERT bobsusedbookstore_dbo.databaselog (DatabaseLogID, PostTime, DatabaseUser, Event, Schema, Object, TSQL, XmlEvent) VALUES (29, CAST('2025-08-25T02:04:16.963' AS DateTime), 'sqladmin', 'CREATE_PROCEDURE', 'dbo', 'uspShoppingLevelAmount', '
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspshoppinglevelamount
    @Percent INT,
    @Amount NUMERIC
AS
BEGIN
    SELECT 
        OrderID,
        ''|'' + CASE 
                WHEN @Percent > 100 THEN
                    CASE 
                        WHEN TotalAmount > @Amount THEN ''more than''
                        ELSE ''less than''
                    END
              END + ''|'' AS AmountLevel
    FROM bobsusedbookstore_dbo.shopping;
END;
', '<EVENT_INSTANCE><EventType>CREATE_PROCEDURE</EventType><PostTime>2025-08-25T02:04:16.963</PostTime><SPID>68</SPID><ServerName>EC2AMAZ-B8QKRL0</ServerName><LoginName>sqladmin</LoginName><UserName>sqladmin</UserName><DatabaseName>BobsUsedBookStore</DatabaseName><SchemaName>dbo</SchemaName><ObjectName>uspShoppingLevelAmount</ObjectName><ObjectType>PROCEDURE</ObjectType><TSQLCommand><SetOptions ANSI_NULLS="ON" ANSI_NULL_DEFAULT="ON" ANSI_PADDING="ON" QUOTED_IDENTIFIER="ON" ENCRYPTED="FALSE" /><CommandText>
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspshoppinglevelamount
    @Percent INT,
    @Amount NUMERIC
AS
BEGIN
    SELECT 
        OrderID,
        ''|'' + CASE 
                WHEN @Percent &gt; 100 THEN
                    CASE 
                        WHEN TotalAmount &gt; @Amount THEN ''more than''
                        ELSE ''less than''
                    END
              END + ''|'' AS AmountLevel
    FROM bobsusedbookstore_dbo.shopping;
END;
</CommandText></TSQLCommand></EVENT_INSTANCE>')
INSERT bobsusedbookstore_dbo.databaselog (DatabaseLogID, PostTime, DatabaseUser, Event, Schema, Object, TSQL, XmlEvent) VALUES (30, CAST('2025-08-25T02:04:16.970' AS DateTime), 'sqladmin', 'CREATE_FUNCTIO', 'dbo', 'ufnCalculateCustomerLifetimeValue', '
CREATE OR REPLACE FUNCTION bobsusedbookstore_dbo.ufncalculatecustomerlifetimevalue
(
    @CustomerID INT
)
RETURNS DECIMAL(10, 2)
AS
BEGIN
    DECLARE @TotalSpent DECIMAL(10, 2);
    DECLARE @FirstOrderDate DATE;
    DECLARE @DaysSinceFirstOrder INT;
    DECLARE @LifetimeValue DECIMAL(10, 2);
    
    SELECT 
        @TotalSpent = SUM(TotalAmount),
        @FirstOrderDate = MIN(OrderDate)
    FROM bobsusedbookstore_dbo.shopping
    WHERE CustomerID = @CustomerID AND TRIM(Status) != ''Refund Requested'';
    
    SET @DaysSinceFirstOrder = DATE_PART('day', @FirstOrderDate, clock_timestamp());
    
    IF @DaysSinceFirstOrder = 0
        SET @LifetimeValue = @TotalSpent;
    ELSE
        SET @LifetimeValue = (@TotalSpent / @DaysSinceFirstOrder) * 365.25;
    
    RETURN @LifetimeValue;
END;
', '<EVENT_INSTANCE><EventType>CREATE_FUNCTION</EventType><PostTime>2025-08-25T02:04:16.970</PostTime><SPID>68</SPID><ServerName>EC2AMAZ-B8QKRL0</ServerName><LoginName>sqladmin</LoginName><UserName>sqladmin</UserName><DatabaseName>BobsUsedBookStore</DatabaseName><SchemaName>dbo</SchemaName><ObjectName>ufnCalculateCustomerLifetimeValue</ObjectName><ObjectType>FUNCTION</ObjectType><TSQLCommand><SetOptions ANSI_NULLS="ON" ANSI_NULL_DEFAULT="ON" ANSI_PADDING="ON" QUOTED_IDENTIFIER="ON" ENCRYPTED="FALSE" /><CommandText>
CREATE OR REPLACE FUNCTION bobsusedbookstore_dbo.ufncalculatecustomerlifetimevalue
(
    @CustomerID INT
)
RETURNS DECIMAL(10, 2)
AS
BEGIN
    DECLARE @TotalSpent DECIMAL(10, 2);
    DECLARE @FirstOrderDate DATE;
    DECLARE @DaysSinceFirstOrder INT;
    DECLARE @LifetimeValue DECIMAL(10, 2);
    
    SELECT 
        @TotalSpent = SUM(TotalAmount),
        @FirstOrderDate = MIN(OrderDate)
    FROM bobsusedbookstore_dbo.shopping
    WHERE CustomerID = @CustomerID AND TRIM(Status) != ''Refund Requested'';
    
    SET @DaysSinceFirstOrder = DATE_PART('day', @FirstOrderDate, clock_timestamp());
    
    IF @DaysSinceFirstOrder = 0
        SET @LifetimeValue = @TotalSpent;
    ELSE
        SET @LifetimeValue = (@TotalSpent / @DaysSinceFirstOrder) * 365.25;
    
    RETURN @LifetimeValue;
END;
</CommandText></TSQLCommand></EVENT_INSTANCE>')
