/****** Object:  StoredProcedure bobsusedbookstore_dbo.uspdeleteauthor    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspdeleteauthor
    @BusinessEntityID int

AS
BEGIN
    

    BEGIN
        DELETE FROM bobsusedbookstore_dbo.author
        WHERE BusinessEntityID = @BusinessEntityID;

        -- Check if the delete was successful
        IF ROW_COUNT = 0
        BEGIN
            RAISERROR('No author found with the provided BusinessEntityID.', 16, 1);
            RETURN;
        END
    EXCEPTION WHEN OTHERS THEN
    -- BEGIN CATCH (handled by EXCEPTION block)
        -- Log the error and re-throw
        EXECUTE bobsusedbookstore_dbo.usplogerror;
        THROW;
    END;
END;


/****** Object:  StoredProcedure bobsusedbookstore_dbo.uspdeleteoldcoupons    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE bobsusedbookstore_dbo.uspdeleteoldcoupons
    @DaysOld INT
AS
BEGIN
    DECLARE @DeletedCount INT = 0;
    
    SELECT TicketID, CreatedDate
    INTO #CouponsToDelete
    FROM bobsusedbookstore_dbo.coupons
    WHERE TRIM(Status) = 'Closed' AND ResolvedDate <= DATEADD(DAY, -@DaysOld, clock_timestamp());

    DECLARE @CouponsCount INT;
    SELECT @CouponsCount = COUNT(*) FROM #CouponsToDelete;

    IF @CouponsCount > 0
    BEGIN
        DELETE t
        FROM bobsusedbookstore_dbo.coupons t
        INNER JOIN #CouponsToDelete d ON t.TicketID = d.TicketID;
        
        SET @DeletedCount = ROW_COUNT;
        RAISE NOTICE '%', 'Deleted ' + CAST(@DeletedCount AS VARCHAR(10)) + ' coupons.';
    END
    ELSE
    BEGIN
        RAISE NOTICE '%', 'No coupons found matching the criteria.';
    END
END;


/****** Object:  StoredProcedure bobsusedbookstore_dbo.uspgetauthormanagers    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON

            
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspgetauthormanagers
    @BusinessEntityID int
AS
BEGIN
    
    WITH EMP_cte(BusinessEntityID, OrganizationNode, FirstName, LastName, JobTitle, RecursionLevel) 
    AS (
        SELECT e.BusinessEntityID, e.OrganizationNode, p.FirstName, p.LastName, e.JobTitle, 0 
        FROM bobsusedbookstore_dbo.author e 
            INNER JOIN bobsusedbookstore_dbo.person as p
            ON p.BusinessEntityID = e.BusinessEntityID
        WHERE e.BusinessEntityID = @BusinessEntityID
        UNION ALL
        SELECT e.BusinessEntityID, e.OrganizationNode, p.FirstName, p.LastName, e.JobTitle, RecursionLevel + 1 
        FROM bobsusedbookstore_dbo.author e 
            INNER JOIN EMP_cte
            ON LEFT(e.OrganizationNode, LENGTH(e.OrganizationNode) - 1) = EMP_cte.OrganizationNode
            INNER JOIN bobsusedbookstore_dbo.person p 
            ON p.BusinessEntityID = e.BusinessEntityID
    )
    SELECT EMP_cte.RecursionLevel, EMP_cte.BusinessEntityID, EMP_cte.FirstName, EMP_cte.LastName, 
        EMP_cte.OrganizationNode AS OrganizationNode, p.FirstName AS 'ManagerFirstName', p.LastName AS 'ManagerLastName'  
    FROM EMP_cte 
        INNER JOIN bobsusedbookstore_dbo.author e 
        ON LEFT(EMP_cte.OrganizationNode, LENGTH(EMP_cte.OrganizationNode) - 1) = e.OrganizationNode
        INNER JOIN bobsusedbookstore_dbo.person p 
        ON p.BusinessEntityID = e.BusinessEntityID
    ORDER BY RecursionLevel, EMP_cte.OrganizationNode
     
END;


/****** Object:  StoredProcedure bobsusedbookstore_dbo.uspgetbillofmaterials    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON

            
CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspgetbillofmaterials
    @StartProductID int,
    @CheckDate TIMESTAMP WITHOUT TIME ZONE
AS
BEGIN
    
    WITH BOM_cte(ProductAssemblyID, ComponentID, ComponentDesc, PerAssemblyQty, StandardCost, ListPrice, BOMLevel, RecursionLevel) 
    AS (
        SELECT b.ProductAssemblyID, b.ComponentID, p.Name, b.PerAssemblyQty, p.StandardCost, p.ListPrice, b.BOMLevel, 0 
        FROM bobsusedbookstore_dbo.billofmaterials b
            INNER JOIN bobsusedbookstore_dbo.product p 
            ON b.ComponentID = p.ProductID 
        WHERE b.ProductAssemblyID = @StartProductID 
            AND @CheckDate >= b.StartDate 
            AND @CheckDate <= COALESCE(b.EndDate, @CheckDate)
        UNION ALL
        SELECT b.ProductAssemblyID, b.ComponentID, p.Name, b.PerAssemblyQty, p.StandardCost, p.ListPrice, b.BOMLevel, RecursionLevel + 1 
        FROM BOM_cte cte
            INNER JOIN bobsusedbookstore_dbo.billofmaterials b 
            ON b.ProductAssemblyID = cte.ComponentID
            INNER JOIN bobsusedbookstore_dbo.product p 
            ON b.ComponentID = p.ProductID 
        WHERE @CheckDate >= b.StartDate 
            AND @CheckDate <= COALESCE(b.EndDate, @CheckDate)
        )
    SELECT b.ProductAssemblyID, b.ComponentID, b.ComponentDesc, SUM(b.PerAssemblyQty) AS TotalQuantity , b.StandardCost, b.ListPrice, b.BOMLevel, b.RecursionLevel
    FROM BOM_cte b
    GROUP BY b.ComponentID, b.ComponentDesc, b.ProductAssemblyID, b.BOMLevel, b.RecursionLevel, b.StandardCost, b.ListPrice
    ORDER BY b.BOMLevel, b.ProductAssemblyID, b.ComponentID
     
END;


