            INNER JOIN EMP_cte
            ON e.OrganizationNode = LEFT(EMP_cte.OrganizationNode, LENGTH(EMP_cte.OrganizationNode) - 1)
            INNER JOIN bobsusedbookstore_dbo.person p 
