/****** Object:  StoredProcedure bobsusedbookstore_dbo.usplogerror    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE bobsusedbookstore_dbo.usplogerror 
    @ErrorLogID int = 0 OUTPUT 
AS
BEGIN
    
    SET @ErrorLogID = 0;

    BEGIN
        IF ERROR_NUMBER() IS NULL
            RETURN;

        INSERT bobsusedbookstore_dbo.errorlog 
            (
            UserName, 
            ErrorNumber, 
            ErrorSeverity, 
            ErrorState, 
            ErrorProcedure, 
            ErrorLine, 
            ErrorMessage
            ) 
        VALUES 
            (
            current_user, 
            ERROR_NUMBER(),
            ERROR_SEVERITY(),
            ERROR_STATE(),
            ERROR_PROCEDURE(),
            ERROR_LINE(),
            ERROR_MESSAGE()
            );

        SET @ErrorLogID = lastval();
    EXCEPTION WHEN OTHERS THEN
    -- BEGIN CATCH (handled by EXCEPTION block)
        RAISE NOTICE '%', 'An error occurred in stored procedure uspLogError: ';
        EXECUTE bobsusedbookstore_dbo.uspprinterror;
        RETURN -1;
    END
END;


/****** Object:  StoredProcedure bobsusedbookstore_dbo.uspprinterror    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE OR REPLACE PROCEDURE bobsusedbookstore_dbo.uspprinterror 
AS
BEGIN
    

    -- Print error information. 
    RAISE NOTICE '%', 'Error ' + CAST(varchar(50), ERROR_NUMBER()) +
          ', Severity ' + CAST(varchar(5), ERROR_SEVERITY()) +
          ', State ' + CAST(varchar(5), ERROR_STATE()) + 
          ', Procedure ' + COALESCE(ERROR_PROCEDURE(), '-') + 
          ', Line ' + CAST(varchar(5), ERROR_LINE());
    RAISE NOTICE '%', ERROR_MESSAGE();
END;


/****** Object:  StoredProcedure bobsusedbookstore_dbo.uspprocessrefunds    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE bobsusedbookstore_dbo.uspprocessrefunds
AS
BEGIN
    

    DECLARE @RefundCount INT = 0;
    DECLARE @MaxID INT;

    SELECT @MaxID = MAX(TicketID) FROM bobsusedbookstore_dbo.coupons;
    
    SELECT OrderID, CustomerID, TotalAmount
    INTO #RefundRequests
    FROM bobsusedbookstore_dbo.shopping
    WHERE TRIM(Status) = 'Refund Requested';
    
    UPDATE o
    SET Status = 'Refunded'
    FROM bobsusedbookstore_dbo.shopping o
    INNER JOIN #RefundRequests r ON o.OrderID = r.OrderID;
    
    INSERT INTO bobsusedbookstore_dbo.coupons (TicketID, CustomerID, OrderID, IssueDescription, CreatedDate, Status)
    SELECT 
        @MaxID + ROW_NUMBER() OVER (ORDER BY OrderID),
        CustomerID,
        OrderID,
        'Refund processed for $' + CAST(TotalAmount AS VARCHAR(20)),
        clock_timestamp(),
        'Closed'
    FROM #RefundRequests;

    SET @RefundCount = ROW_COUNT;

    RAISE NOTICE '%', 'Processed ' + CAST(@RefundCount AS VARCHAR(10)) + ' refunds.';

    DROP TABLE #RefundRequests;
END;


/****** Object:  StoredProcedure bobsusedbookstore_dbo.uspshoppinglevelamount    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE bobsusedbookstore_dbo.uspshoppinglevelamount
    @Percent INT,
    @Amount NUMERIC
AS
BEGIN
    SELECT 
        OrderID,
        '|' + CASE 
                WHEN @Percent > 100 THEN
                    CASE 
                        WHEN TotalAmount > @Amount THEN 'more than'
                        ELSE 'less than'
                    END
              END + '|' AS AmountLevel
    FROM bobsusedbookstore_dbo.shopping;
END;


