/****** Object:  DdlTrigger ddlDatabaseTriggerLog    Script Date: 8/25/2025 8:23:45 AM ******/
SET ANSI_NULLS ON

SET QUOTED_IDENTIFIER ON


CREATE TRIGGER ddlDatabaseTriggerLog ON DATABASE 
FOR DDL_DATABASE_LEVEL_EVENTS AS 
BEGIN
    

    DECLARE @data XML;
    DECLARE @schema VARCHAR(128);
    DECLARE @object VARCHAR(128);
    DECLARE @eventType VARCHAR(128);

    SET @data = EVENTDATA();
    SET @eventType = @data.value('(/EVENT_INSTANCE/EventType)[1]', 'VARCHAR(128)');
    SET @schema = @data.value('(/EVENT_INSTANCE/SchemaName)[1]', 'VARCHAR(128)');
    SET @object = @data.value('(/EVENT_INSTANCE/ObjectName)[1]', 'VARCHAR(128)') 

    IF @object IS NOT NULL
        RAISE NOTICE '%', '  ' + @eventType + ' - ' + @schema + '.' + @object;
    ELSE
        RAISE NOTICE '%', '  ' + @eventType + ' - ' + @schema;

    IF @eventType IS NULL
        RAISE NOTICE '%', CAST(TEXT, @data);

    INSERT bobsusedbookstore_dbo.databaselog 
        (
        PostTime, 
        DatabaseUser, 
        Event, 
        Schema, 
        Object, 
        TSQL, 
        XmlEvent
        ) 
    VALUES 
        (
        clock_timestamp(), 
        CAST(VARCHAR(128), CURRENT_USER), 
        @eventType, 
        CAST(VARCHAR(128), @schema), 
        CAST(VARCHAR(128), @object), 
        @data.value('(/EVENT_INSTANCE/TSQLCommand)[1]', 'TEXT'), 
        @data
        );
END;


ENABLE TRIGGER ddlDatabaseTriggerLog ON DATABASE



